#include "TravelStateMachine.hpp"
#include <algorithm>
#include <cmath>
namespace elysium::travel {
bool TravelStateMachine::legal(TravelState a,TravelState b)const{ switch(a){case TravelState::SurfaceLanded:return b==TravelState::AtmosphericAscent;case TravelState::AtmosphericAscent:return b==TravelState::NearOrbit||b==TravelState::SurfaceLanded;case TravelState::NearOrbit:return b==TravelState::PulseTransit||b==TravelState::SystemFreeFlight||b==TravelState::SurfaceLanded;case TravelState::PulseTransit:return b==TravelState::SystemFreeFlight||b==TravelState::Interception;case TravelState::SystemFreeFlight:return b==TravelState::WarpCharge||b==TravelState::Docked||b==TravelState::Interception||b==TravelState::NearOrbit;case TravelState::WarpCharge:return b==TravelState::WarpTransition||b==TravelState::SystemFreeFlight||b==TravelState::Interception;case TravelState::WarpTransition:return b==TravelState::SystemFreeFlight;case TravelState::Interception:return b==TravelState::SystemFreeFlight||b==TravelState::WarpCharge;case TravelState::Docked:return b==TravelState::SystemFreeFlight;} return false; }
TransitionResult TravelStateMachine::transition(TravelState to,TravelContext& c){ TransitionResult out{false,"",0,record_.state}; if(!legal(record_.state,to)){out.reason="illegal transition";return out;} if((to==TravelState::AtmosphericAscent||to==TravelState::NearOrbit)&&!c.flightAllowed){out.reason="flight constraint";return out;} if(to==TravelState::Docked&&(!c.dockingAvailable||!c.hasDockingCollar)){out.reason="docking unavailable";return out;} if(to==TravelState::WarpCharge&&!c.routeKnown){out.reason="unknown route";return out;} if(to==TravelState::WarpTransition){ double cost=std::max(0.0,std::isfinite(c.warpCost)?c.warpCost:0.0); if(!record_.costSettled){ if(c.fuel<cost){out.reason="insufficient fuel";return out;} c.fuel-=cost; record_.costSettled=true; out.fuelConsumed=cost; } } record_.state=to; ++record_.transitionVersion; if(to==TravelState::SystemFreeFlight&&record_.costSettled)record_.costSettled=false; out.accepted=true; out.state=to; return out; }
void TravelStateMachine::recoverFromTornState(){ if(record_.state==TravelState::WarpTransition){record_.state=TravelState::SystemFreeFlight; record_.costSettled=false;} }
}